/* Post Title with Line Clamp */
.vd-post-title {
    font-size: 17px;
    font-weight: 700;
    line-height: 1.4;
    margin: 0;
    display: -webkit-box;
    -webkit-line-clamp: 2;
    -webkit-box-orient: vertical;
    overflow: hidden;
    word-break: break-word;
    hyphens: auto;
    min-height: calc(2 * 1.4em); /* Reserve space for 2 lines */
}

.vd-post-title a {
