/* ==========================================================================
   Loading States
   ========================================================================== */

.vd-loading {
    position: relative;
    pointer-events: none;
    opacity: 0.7;
}

.vd-loading::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: rgba(255, 255, 255, 0.8);
    z-index: 99;
}

.vd-loading::after {
    content: '';
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    width: 40px;
    height: 40px;
    border: 3px solid #f3f3f3;
    border-top: 3px solid #007cba;
    border-radius: 50%;
    animation: vd-spin 1s linear infinite;
    z-index: 100;
}

@keyframes vd-spin {
    0% { transform: translate(-50%, -50%) rotate(0deg); }
    100% { transform: translate(-50%, -50%) rotate(360deg); }
}

/* Skeleton loading */
.vd-skeleton {
    background: linear-gradient(90deg, #f0f0f0 25%, #e0e0e0 50%, #f0f0f0 75%);
    background-size: 200% 100%;
    animation: vd-skeleton-loading 1.5s infinite;
    display: block;
}

.vd-skeleton-card {
    background: #fff;
    border-radius: 8px;
    overflow: hidden;
    box-shadow: 0 2px 15px rgba(0, 0, 0, 0.05);
    height: 380px;
}

/* Posts Skeleton Loading */
.vd-skeleton-post-card {
    background: #fff;
    border-radius: 16px;
    overflow: hidden;
    box-shadow: 0 4px 16px rgba(0, 0, 0, 0.06);
    height: 400px;
    display: flex;
    flex-direction: column;
}

.vd-skeleton-post-thumb {
    width: 100%;
    aspect-ratio: 16/9;
    background: linear-gradient(90deg, #f0f0f0 25%, #e6e6e6 50%, #f0f0f0 75%);
    background-size: 200% 100%;
    animation: vd-skeleton-loading 1.8s infinite;
}

.vd-skeleton-post-body {
    padding: 16px;
    flex: 1;
    display: flex;
    flex-direction: column;
    gap: 8px;
}

.vd-skeleton-post-meta {
    height: 12px;
    width: 50%;
    border-radius: 6px;
}

.vd-skeleton-post-title {
    height: 18px;
    margin: 8px 0;
    border-radius: 4px;
}

.vd-skeleton-post-title:nth-child(2) { width: 90%; }
.vd-skeleton-post-title:nth-child(3) { width: 70%; }

.vd-skeleton-post-excerpt {
    height: 14px;
    margin: 4px 0;
    border-radius: 4px;
}

.vd-skeleton-post-excerpt:nth-child(1) { width: 95%; }
.vd-skeleton-post-excerpt:nth-child(2) { width: 75%; }

.vd-skeleton-post-footer {
    height: 24px;
    width: 100px;
    margin-top: auto;
    border-radius: 12px;
}

.vd-skeleton-image {
    width: 100%;
    height: 250px;
    background: linear-gradient(90deg, #f0f0f0 25%, #e6e6e6 50%, #f0f0f0 75%);
    background-size: 200% 100%;
    animation: vd-skeleton-loading 1.8s infinite;
}

.vd-skeleton-content {
    padding: 20px;
}

.vd-skeleton-title {
    height: 20px;
    margin-bottom: 10px;
    width: 80%;
    border-radius: 4px;
}

.vd-skeleton-text {
    height: 16px;
    margin-bottom: 8px;
    border-radius: 4px;
}

.vd-skeleton-text:nth-child(2) { width: 90%; }
.vd-skeleton-text:nth-child(3) { width: 60%; }

.vd-skeleton-button {
    height: 40px;
    margin-top: 15px;
    border-radius: 6px;
}

@keyframes vd-skeleton-loading {
    0% { background-position: 200% 0; }
    100% { background-position: -200% 0; }
}

/* Processing state */
.vd-processing {
    opacity: 0.6;
    pointer-events: none;
    position: relative;
}

.vd-processing::after {
    content: '';
    position: absolute;
    right: 10px;
    top: 50%;
    transform: translateY(-50%);
    width: 12px;
    height: 12px;
    border: 2px solid #ccc;
    border-top: 2px solid #007cba;
    border-radius: 50%;
    animation: vd-spin 0.8s linear infinite;
}

/* ==========================================================================
   Notices & Messages
   ========================================================================== */

.vd-no-results {
