    justify-content: center;
    gap: 6px;
    margin: 0;
    padding: 0;
    list-style: none;
    flex-wrap: wrap;
}


/* Loading indicator */
.vd-pagination-loading {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
    margin-top: 16px;
    padding: 12px;
    background: rgba(0, 124, 186, 0.1);
    border-radius: 8px;
    color: #007cba;
    font-size: 14px;
    font-weight: 500;
}

.vd-spinner {
    width: 16px;
    height: 16px;
    border: 2px solid transparent;
    border-top: 2px solid #007cba;
    border-radius: 50%;
    animation: vd-spin 1s linear infinite;
}


/* ==========================================================================
