/* Menu title - Hidden */
.vd-menu-title {
    display: none !important;
}

/* Base menu styles */
.vd-sidebar-menu {
    list-style: none;
    margin: 0;
    padding: 0;
}

.vd-sidebar-menu li {
    margin: 0;
    position: relative;
}

/* Menu links */
.vd-sidebar-menu a {
    display: block;
    padding: 8px 12px 8px 25px;
    text-decoration: none !important;
    color: #333 !important;
    font-size: 14px;
    transition: all 0.2s ease;
    position: relative;
    z-index: 2;
    font-weight: 400 !important;
    font-style: normal !important;
}

/* Cursor for expandable items */
.vd-has-children > a {
    cursor: pointer;
}

/* Level specific padding */
.vd-menu-item.vd-level-2 > a {
    padding-left: 45px;
}

.vd-menu-item.vd-level-3 > a {
    padding-left: 65px;
}

.vd-menu-item.vd-level-4 > a {
    padding-left: 85px;
}

.vd-menu-item.vd-level-5 > a {
    padding-left: 105px;
}

/* Hover effect */
.vd-sidebar-menu a:hover {
    background-color: #f5f5f5;
    color: #333 !important;
}

/* Active state - bold only */
.vd-sidebar-menu a.active {
    font-weight: 700 !important;
    color: #333 !important;
    background-color: transparent !important;
}

/* Submenu container */
.vd-submenu {
    list-style: none;
    margin: 0;
    padding: 0;
    display: none;
    transition: all 0.2s ease;
    overflow: hidden;
}

.vd-menu-item.vd-expanded > .vd-submenu {
    display: block;
}

/* Faster transitions when transitioning */
.vd-transitioning .vd-submenu {
    transition: all 0.15s ease;
}

.vd-transitioning .vd-menu-item {
    transition: opacity 0.15s ease;
}

/* Mobile responsive */
@media (max-width: 768px) {
    .vd-menu-section {
        padding: 10px;
    }


    .vd-sidebar-menu a {
        padding: 8px 10px 8px 20px;
    }

    .vd-menu-item.vd-level-2 > a {
        padding-left: 40px;
    }

    .vd-menu-item.vd-level-3 > a {
        padding-left: 60px;
    }

    .vd-menu-item.vd-level-4 > a {
        padding-left: 80px;
    }

    .vd-menu-item.vd-level-5 > a {
        padding-left: 100px;
    }
}

/* Smart tree display - hide non-relevant items */
.vd-menu-item.vd-hidden {
    display: none !important;
}

/* Ensure smooth transitions */
.vd-menu-item {
    transition: opacity 0.2s ease;
}

/* Force normal style for all links */
.vd-sidebar-menu a,
.vd-sidebar-menu a:link,
.vd-sidebar-menu a:visited,
.vd-sidebar-menu a:focus,
.vd-sidebar-menu a:active {
    font-style: normal !important;
    color: #333 !important;
    opacity: 1 !important;
    text-decoration: none !important;
}

/* Override any theme colors */
.vd-sidebar .vd-sidebar-menu a,
.vd-sidebar .vd-sidebar-menu a:visited {
    color: #333 !important;
}

/* Ensure parent items are not styled differently */
.vd-has-active-child > a {
    font-weight: 400 !important;
    font-style: normal !important;
    color: #333 !important;
}

/* Force remove any tree lines from other CSS */
.vd-sidebar-menu *::before,
.vd-sidebar-menu *::after {
    content: none !important;
    display: none !important;
    background: none !important;
    border: none !important;
}

/* Ensure clean display */
.vd-menu-item,
.vd-submenu {
    border: none !important;
    background: none !important;
}

.vd-menu-item::before,
.vd-menu-item::after,
.vd-submenu::before,
.vd-submenu::after {
    content: none !important;
    display: none !important;
}

/**
 * Vidieu Select Options Open Quickview Sidebar
 * 
 * Opens NASA quickview sidebar when "Tùy chọn" button is clicked
 * in plugin product sections
 * 
 * @package VidieuHomeSections
 * @version 1.0.0
 */

(function($) {
    'use strict';

    if (typeof $ === 'undefined') {
        return;
    }

    var VDHome = window.VDHome || {};

    /**
     * Initialize select options to open quickview
     */
    VDHome.initSelectOptionsOpenQuickview = function(root) {
        root = root || document;
        var self = this;

        // Find container for event delegation
        var $containers = $(root).find('div[id^="vd-products-"]');
        if (!$containers.length && $(root).is('div[id^="vd-products-"]')) {
            $containers = $(root);
        }

        if (!$containers.length) {
            return;
        }

        // Remove previous handlers to prevent double-binding
        $containers.off('click.vdhs');

        // Attach delegated event handler
        $containers.on('click.vdhs', '.vd-buy-now-button', function(e) {
            var $btn = $(this);

            // Check if this is truly a select-options button
            if (!self.isSelectOptionsButton($btn)) {
                // Don't prevent default for "Mua ngay" buttons
                return;
            }

            // For select options, prevent default
            e.preventDefault();
            e.stopPropagation();

            // Get product info
            var $product = $btn.closest('li.product, li.product-item, .product-item, .item-product, .type-product');
            if (!$product.length) {
                $product = $btn.closest('li');
            }
            if (!$product.length) {
                return;
            }

            // Get product ID
            var productId = self.getProductId($product, $btn);
            if (!productId) {
                return;
            }

            // Open NASA quickview sidebar
            self.openNasaQuickviewSidebar(productId, $product);
        });
    };

    /**
     * Check if button is a select-options button
     */
    VDHome.isSelectOptionsButton = function($btn) {
        // Check data-action first - this is the most reliable
        var dataAction = $btn.attr('data-action');
        if (dataAction === 'buy-now' || dataAction === 'add-to-cart') {
            return false;
        }

        if (dataAction === 'select-options') {
            return true;
        }

        // Check by text content
        var text = $btn.text().trim().toLowerCase();
        if (text === 'mua ngay' || text === 'buy now' || text.includes('mua')) {
            return false;
        }

        if (text === 'tùy chọn' || text === 'select options' || text.includes('chọn')) {
            return true;
        }

        // Check by class as last resort
        if ($btn.hasClass('vd-buy-now-variable')) {
            if (text !== 'mua ngay' && text !== 'buy now') {
                return true;
            }
        }

        return false;
    };

    /**
     * Get product ID from various sources
     */
    VDHome.getProductId = function($product, $btn) {
        var productId = null;

        // Try 1: From .nasa-product-content-variable-warp
        var $varWrap = $product.find('.nasa-product-content-variable-warp[data-product_id]');
        if ($varWrap.length) {
            productId = $varWrap.attr('data-product_id');
            if (productId) return productId;
        }

        // Try 2: From button data attributes
        productId = $btn.attr('data-product_id') || $btn.data('product_id') || $btn.attr('data-product-id');
        if (productId) return productId;

        // Try 3: From product container
        productId = $product.attr('data-product_id') || $product.data('product-id') || $product.attr('data-product-id');
        if (productId) return productId;

        // Try 4: From quickview icon in same product
        var $quickview = $product.find('.quick-view[data-prod]');
        if ($quickview.length) {
            productId = $quickview.attr('data-prod');
            if (productId) return productId;
        }

        // Try 5: From href attribute parsing
        var href = $btn.attr('href');
        if (href && href.includes('add-to-cart=')) {
            var match = href.match(/add-to-cart=(\d+)/);
            if (match && match[1]) {
                productId = match[1];
                return productId;
            }
        }

        return null;
    };

    /**
     * Open NASA quickview sidebar for product
     */
    VDHome.openNasaQuickviewSidebar = function(productId, $product) {
        // Check if sidebar exists
        if (!$('#nasa-quickview-sidebar').length) {
            return;
        }

        // Direct AJAX call using NASA theme's mechanism
        if (typeof nasa_params_quickview !== 'undefined' && nasa_params_quickview.wc_ajax_url) {
            var _urlAjax = nasa_params_quickview.wc_ajax_url.toString().replace('%%endpoint%%', 'nasa_quick_view');

            var _data = {
                product: productId,
                quickview: 'sidebar'
            };

            // Ensure black-window exists
            if (!$('.black-window').length) {
                $('body').append('<div class="black-window"></div>');
            }

            // Show loader
            $('.black-window').fadeIn(200).addClass('desk-window');
            $('#nasa-quickview-sidebar').addClass('nasa-active');
            $('#nasa-quickview-sidebar #nasa-quickview-sidebar-content').html('<div class="nasa-loader"></div>');

            // Add close button handler
            $('.black-window').off('click.vdQuickview').on('click.vdQuickview', function(e) {
                if ($(e.target).hasClass('black-window')) {
                    $('#nasa-quickview-sidebar').removeClass('nasa-active');
                    $('.black-window').fadeOut(200).removeClass('desk-window');
                }
            });

            $.ajax({
                url: _urlAjax,
                type: 'post',
                dataType: 'json',
                data: _data,
                cache: false,
                success: function(response) {
                    if (response && response.content) {
                        $('#nasa-quickview-sidebar #nasa-quickview-sidebar-content').html('<div class="product-lightbox">' + response.content + '</div>');

                        setTimeout(function() {
                            $('#nasa-quickview-sidebar #nasa-quickview-sidebar-content .product-lightbox').addClass('nasa-loaded');
                            $('body').trigger('nasa_after_quickview_timeout');
                            $('body').trigger('nasa_after_quickview');

                            // Initialize variations form if exists
                            var $form = $('.product-lightbox').find('.variations_form');
                            if ($form.length) {
                                $('body').trigger('init_quickview_variations_form', [$form]);
                            }
                        }, 200);
                    }
                },
                error: function() {
                    $('#nasa-quickview-sidebar').removeClass('nasa-active');
                    $('.black-window').fadeOut(200).removeClass('desk-window');
                }
            });
        }
    };

    /**
     * Re-initialize after AJAX updates
     */
    VDHome.reinitSelectOptionsQuickview = function() {
        VDHome.initSelectOptionsOpenQuickview();
        VDHome.overrideNasaQuickview();
    };

    /**
     * Override NASA quickview to prevent opening in plugin sections
     */
    VDHome.overrideNasaQuickview = function() {
        // Wait a bit to ensure theme handler is loaded
        setTimeout(function() {
            // Store original NASA quickview handler
            var originalNasaHandler = null;

            // Check if there's a click handler on body for .quick-view
            var bodyHandlers = $._data(document.body, 'events');
            if (bodyHandlers && bodyHandlers.click) {
                bodyHandlers.click.forEach(function(handler) {
                    if (handler.selector === '.quick-view') {
                        originalNasaHandler = handler.handler;
                    }
                });
            }

            // Remove the original handler
            $('body').off('click', '.quick-view');

            // Add our wrapped handler
            $('body').on('click', '.quick-view', function(e) {
                var $this = $(this);

                // Check if this is in a plugin section
                if ($this.closest('.vd-home-section.vd-home-products').length) {
                    // Don't call NASA handler, let custom quickview handle it
                    return;
                }

                // For quickview outside plugin sections, call original handler
                if (originalNasaHandler) {
                    originalNasaHandler.call(this, e);
                }
            });
        }, 100);
    };

    // Initialize on document ready
    $(document).ready(function() {
        // Add CSS fixes for NASA quickview sidebar
        var fixCSS = `
            <style id="vd-quickview-fix">
                /* Ensure NASA quickview sidebar is visible */
                #nasa-quickview-sidebar {
                    display: block !important;
                    visibility: visible !important;
                    opacity: 1 !important;
                }

                #nasa-quickview-sidebar.nasa-active {
                    transform: translateX(0) !important;
                    right: 0 !important;
                }

                /* Ensure black window is visible when needed */
                .black-window.desk-window {
                    display: block !important;
                    visibility: visible !important;
                    opacity: 0.8 !important;
                    z-index: 9998 !important;
                }

                /* Fix z-index for sidebar */
                #nasa-quickview-sidebar {
                    z-index: 9999 !important;
                }

                /* Remove any hiding from custom quickview */
                body.vd-custom-quickview-active #nasa-quickview-sidebar {
                    display: block !important;
                }
            </style>
        `;

        $('head').append(fixCSS);

        VDHome.initSelectOptionsOpenQuickview();
        VDHome.overrideNasaQuickview();
    });

    // Re-initialize after AJAX events
    $(document).on('vidieu_products_filtered vidieu_products_page_loaded vidieu_items_loaded', function() {
        VDHome.reinitSelectOptionsQuickview();
    });

    // Legacy event names support
    $(document).on('vd_products_filtered vd_products_page_loaded vd_items_loaded', function() {
        VDHome.reinitSelectOptionsQuickview();
    });

    // NASA theme events
    $(document).on('nasa_after_load nasa_refresh_shop', function() {
        setTimeout(function() {
            VDHome.reinitSelectOptionsQuickview();
        }, 200);
    });

    // Monitor for dynamic content changes with MutationObserver
    if (typeof MutationObserver !== 'undefined') {
        var observer = new MutationObserver(function(mutations) {
            var shouldReinit = false;

            mutations.forEach(function(mutation) {
                if (mutation.type === 'childList' && mutation.addedNodes.length) {
                    // Check if products were added
                    for (var i = 0; i < mutation.addedNodes.length; i++) {
                        var node = mutation.addedNodes[i];
                        if (node.nodeType === 1) { // Element node
                            if ($(node).hasClass('product') || $(node).find('.product').length) {
                                shouldReinit = true;
                                break;
                            }
                        }
                    }
                }
            });

            if (shouldReinit) {
                // Debounce re-initialization
                clearTimeout(VDHome._reinitTimeout);
                VDHome._reinitTimeout = setTimeout(function() {
                    VDHome.reinitSelectOptionsQuickview();
                }, 150);
            }
        });

        // Observe product containers
        $('div[id^="vd-products-"]').each(function() {
            observer.observe(this, {
                childList: true,
                subtree: true
            });
        });
    }

    // Expose to global scope
    window.VDHome = VDHome;

})(jQuery);

/**
 * Optimized AJAX Handler for Vidieu Home Sections
 * 
 * Implements request debouncing, caching, and performance optimizations
 * to reduce AJAX response times and improve user experience
 */

(function($) {
    'use strict';

    // Performance optimization module
    window.VidieuAjaxOptimized = {

        // Configuration
        config: {
            debounceDelay: 300, // ms
            cacheExpiration: 300000, // 5 minutes
            maxCacheSize: 50, // Maximum cached responses
            enableClientCache: true,
            enableRequestQueue: true,
            enableImagePreload: true
        },

        // State management
        state: {
            activeRequests: new Map(),
            cache: new Map(),
            requestQueue: [],
            isProcessing: false
        },

        /**
         * Initialize optimizations
         */
        init: function() {
            this.bindEvents();
            this.setupImageLazyLoading();
            this.preloadCriticalData();

            // Monitor performance
            if (window.performance && window.performance.mark) {
                window.performance.mark('vd-ajax-init');
            }
        },

        /**
         * Bind optimized event handlers
         */
        bindEvents: function() {
            var self = this;

            // Debounced filter handler
            var debouncedFilter = this.debounce(function(params) {
                self.filterProducts(params);
            }, this.config.debounceDelay);

            // Category filter with debouncing
            $(document).on('click', '.vd-sidebar-menu a[data-term-id]', function(e) {
                e.preventDefault();

                var $link = $(this);
                var params = self.extractParams($link);

                // Cancel any pending requests
                self.cancelPendingRequests(params.section_id);

                // Update UI immediately
                $('.vd-sidebar-menu a').removeClass('active');
                $link.addClass('active');

                // Show loading state
                self.showLoadingState(params.section_id);

                // Execute with debouncing
                debouncedFilter(params);
            });

            // Pagination with request cancellation
            $(document).on('click', '.vd-pagination-wrapper a.page-numbers', function(e) {
                e.preventDefault();

                var $link = $(this);
                var params = self.extractPaginationParams($link);

                // Immediate feedback
                $link.addClass('loading');

                // Execute without debouncing for pagination
                self.filterProducts(params);
            });
        },

        /**
         * Optimized product filtering
         */
        filterProducts: function(params) {
            var self = this;

            // Check client-side cache first
            var cacheKey = this.generateCacheKey(params);
            var cachedData = this.getFromCache(cacheKey);

            if (cachedData) {
                this.renderProducts(cachedData, params);
                return;
            }

            // Mark performance
            if (window.performance) {
                window.performance.mark('vd-ajax-start');
            }

            // Prepare request
            var request = $.ajax({
                url: vidieu_ajax.ajax_url,
                type: 'POST',
                data: $.extend({
                    action: 'vidieu_filter_products',
                    nonce: vidieu_ajax.nonce
                }, params),
                beforeSend: function(xhr) {
                    // Add performance headers
                    xhr.setRequestHeader('X-Requested-With', 'XMLHttpRequest');

                    // Store active request
                    self.state.activeRequests.set(params.section_id, xhr);

                    // Cancel previous request for same section
                    var prevRequest = self.state.activeRequests.get(params.section_id);
                    if (prevRequest && prevRequest !== xhr) {
                        prevRequest.abort();
                    }
                }
            });

            // Handle response
            request.done(function(response) {
                if (response.success) {
                    // Cache successful response
                    self.saveToCache(cacheKey, response.data);

                    // Render products
                    self.renderProducts(response.data, params);

                    // Preload next page
                    if (params.page < response.data.max_pages) {
                        self.preloadNextPage(params);
                    }

                    // Performance measurement
                    if (window.performance) {
                        window.performance.mark('vd-ajax-end');
                        window.performance.measure('vd-ajax-duration', 'vd-ajax-start', 'vd-ajax-end');

                        var measure = window.performance.getEntriesByName('vd-ajax-duration')[0];
                    }
                }
            }).fail(function(xhr) {
                if (xhr.statusText !== 'abort') {
                    self.showError(params.section_id);
                }
            }).always(function() {
                self.state.activeRequests.delete(params.section_id);
                self.hideLoadingState(params.section_id);
            });
        },

        /**
         * Render products with optimizations
         */
        renderProducts: function(data, params) {
            var $section = $('#' + params.section_id);
            var $container = $section.find('.vd-products-grid');
            var $pagination = $section.find('.vd-pagination-wrapper');

            // Use requestAnimationFrame for smooth rendering
            requestAnimationFrame(function() {
                // Update content
                $container.html(data.html);

                // Update pagination if exists
                if (data.pagination) {
                    $pagination.html(data.pagination);
                }

                // Lazy load images
                if ('IntersectionObserver' in window) {
                    var images = $container.find('img[loading="lazy"]');
                    images.each(function() {
                        var img = this;
                        var observer = new IntersectionObserver(function(entries) {
                            if (entries[0].isIntersecting) {
                                img.src = img.dataset.src || img.src;
                                observer.unobserve(img);
                            }
                        });
                        observer.observe(img);
                    });
                }

                // Trigger custom event
                $(document).trigger('vd:products:rendered', [data, params]);
            });
        },

        /**
         * Cache management
         */
        generateCacheKey: function(params) {
            return 'vd_' + JSON.stringify(params);
        },

        getFromCache: function(key) {
            if (!this.config.enableClientCache) return null;

            var cached = this.state.cache.get(key);
            if (cached && Date.now() - cached.timestamp < this.config.cacheExpiration) {
                return cached.data;
            }

            // Remove expired entry
            if (cached) {
                this.state.cache.delete(key);
            }

            return null;
        },

        saveToCache: function(key, data) {
            if (!this.config.enableClientCache) return;

            // Limit cache size
            if (this.state.cache.size >= this.config.maxCacheSize) {
                // Remove oldest entry
                var firstKey = this.state.cache.keys().next().value;
                this.state.cache.delete(firstKey);
            }

            this.state.cache.set(key, {
                data: data,
                timestamp: Date.now()
            });
        },

        /**
         * Preload next page for faster navigation
         */
        preloadNextPage: function(currentParams) {
            var nextParams = $.extend({}, currentParams, {
                page: currentParams.page + 1
            });

            var cacheKey = this.generateCacheKey(nextParams);

            // Skip if already cached
            if (this.getFromCache(cacheKey)) return;

            // Preload in background with low priority
            setTimeout(function() {
                $.ajax({
                    url: vidieu_ajax.ajax_url,
                    type: 'POST',
                    data: $.extend({
                        action: 'vidieu_filter_products',
                        nonce: vidieu_ajax.nonce
                    }, nextParams),
                    success: function(response) {
                        if (response.success) {
                            VidieuAjaxOptimized.saveToCache(cacheKey, response.data);
                        }
                    }
                });
            }, 1000);
        },

        /**
         * UI State Management
         */
        showLoadingState: function(sectionId) {
            var $section = $('#' + sectionId);
            $section.find('.vd-products-grid').addClass('vd-loading');
        },

        hideLoadingState: function(sectionId) {
            var $section = $('#' + sectionId);
            $section.find('.vd-products-grid').removeClass('vd-loading');
        },

        showError: function(sectionId) {
            var $section = $('#' + sectionId);
            var $container = $section.find('.vd-products-grid');

            $container.html(
                '<div class="vd-error-message">' +
                    '<p>Unable to load products. Please try again.</p>' +
                    '<button class="vd-retry-button">Retry</button>' +
                '</div>'
            );
        },

        /**
         * Cancel pending requests
         */
        cancelPendingRequests: function(sectionId) {
            var request = this.state.activeRequests.get(sectionId);
            if (request && request.readyState !== 4) {
                request.abort();
                this.state.activeRequests.delete(sectionId);
            }
        },

        /**
         * Extract parameters from elements
         */
        extractParams: function($element) {
            var $section = $element.closest('.vd-home-section');
            var sectionType = $section.hasClass('vd-home-products') ? 'products' : 'posts';

            return {
                category: $element.data('term-id') || '',
                taxonomy: $element.data('taxonomy') || (sectionType === 'products' ? 'product_cat' : 'category'),
                section_id: $section.attr('id'),
                section_type: sectionType,
                page: 1,
                per_page: $section.data('per-page') || (sectionType === 'products' ? 12 : 9),
                columns: $section.data('columns') || (sectionType === 'products' ? 4 : 3)
            };
        },

        extractPaginationParams: function($element) {
            var $wrapper = $element.closest('.vd-pagination-wrapper');
            return {
                category: $wrapper.data('category') || '',
                taxonomy: $wrapper.data('taxonomy') || 'product_cat',
                section_id: $wrapper.data('section-id'),
                page: $element.data('page') || 1,
                per_page: $wrapper.data('per-page') || 12,
                columns: $wrapper.data('columns') || 4
            };
        },

        /**
         * Setup lazy loading for images
         */
        setupImageLazyLoading: function() {
            if ('IntersectionObserver' in window) {
                var imageObserver = new IntersectionObserver(function(entries, observer) {
                    entries.forEach(function(entry) {
                        if (entry.isIntersecting) {
                            var img = entry.target;
                            img.src = img.dataset.src || img.src;
                            img.classList.add('loaded');
                            observer.unobserve(img);
                        }
                    });
                }, {
                    rootMargin: '50px 0px',
                    threshold: 0.01
                });

                // Observe all lazy images
                document.querySelectorAll('img[loading="lazy"]').forEach(function(img) {
                    imageObserver.observe(img);
                });
            }
        },

        /**
         * Preload critical data on page load
         */
        preloadCriticalData: function() {
            // Preload first category for each section
            $('.vd-home-section').each(function() {
                var $section = $(this);
                var $firstCategory = $section.find('.vd-sidebar-menu a:first');

                if ($firstCategory.length) {
                    var params = VidieuAjaxOptimized.extractParams($firstCategory);
                    var cacheKey = VidieuAjaxOptimized.generateCacheKey(params);

                    // Preload if not cached
                    if (!VidieuAjaxOptimized.getFromCache(cacheKey)) {
