table.compare-list .bundled_product .details .bundled_product_title,
table.compare-list .bundled_product .details .price {
    font-size: 90%;
}
table.compare-list .bundled_product .details .price {
    margin-bottom: 0;
}

/*########### REUQEST A QUOTE ############*/

table.compare-list .yith-ywraq-add-to-quote {
