/**
 * Hide NASA/Elessi Breadcrumb - Static Blocks Dashboard
 * 
 * This CSS provides immediate hiding before JavaScript removal
 */

/* Hide breadcrumb with specific class combination */
span.nasa-flex.jc {
    display: none !important;
    visibility: hidden !important;
    height: 0 !important;
    overflow: hidden !important;
}

/* Fallback for browsers without :has() support */
span.nasa-flex.jc i.pe-7s-news-paper,
span.nasa-flex.jc i.pe7-icon.pe-7s-news-paper,
span.nasa-flex.jc i.fa-angle-right {
    display: none !important;
}

/* Modern browsers with :has() support */
@supports selector(:has(*)) {
    /* More specific targeting if needed */
    span.nasa-flex.jc:has(i.pe-7s-news-paper),
    span.nasa-flex.jc:has(i.pe7-icon.pe-7s-news-paper) {
        display: none !important;
    }

    /* Target breadcrumb containing specific text */
    span.nasa-flex.jc:has(i.fa-angle-right) {
        display: none !important;
    }

    /* Hide parent container if it only contains the breadcrumb */
    .nasa-breadcrumb-wrap:has(> span.nasa-flex.jc:only-child),
    .breadcrumb-wrap:has(> span.nasa-flex.jc:only-child) {
        display: none !important;
    }
}

/* Admin specific hiding */
body.wp-admin span.nasa-flex.jc,
body.admin-bar span.nasa-flex.jc {
    display: none !important;
}

/* Frontend specific hiding */
body:not(.wp-admin) span.nasa-flex.jc {
    display: none !important;
}

/* Hide with animation to prevent flash */
@keyframes hideBreadcrumb {
    from { opacity: 1; }
    to { opacity: 0; }
}

span.nasa-flex.jc {
    animation: hideBreadcrumb 0.1s forwards;
}

/**
 * Hide Empty Top Bar CSS
 * Hides top bar when it doesn't contain login/register content
 */

/* Hide top bar marked as empty by JavaScript */
#top-bar.hidden-empty-topbar,
.top-bar.hidden-empty-topbar {
    display: none !important;
    visibility: hidden !important;
    height: 0 !important;
    overflow: hidden !important;
    margin: 0 !important;
    padding: 0 !important;
    border: none !important;
}

/* Remove spacing when top bar is hidden */
body:has(#top-bar.hidden-empty-topbar),
body:has(.top-bar.hidden-empty-topbar) {
    padding-top: 0 !important;
}

/* Fallback for browsers without :has() */
body.topbar-hidden {
    padding-top: 0 !important;
}

/* Adjust header positioning when topbar is hidden */
.hidden-empty-topbar + header,
.hidden-empty-topbar ~ header,
body:has(.hidden-empty-topbar) header {
    margin-top: 0 !important;
}

/* Mobile specific hiding */
@media (max-width: 767px) {
    /* If login/register is shown elsewhere on mobile, hide topbar */
    body.mobile-menu-has-account #top-bar,
    body.mobile-menu-has-account .top-bar {
        display: none !important;
    }
}

/* Smooth transition when hiding */
#top-bar,
.top-bar {
    transition: height 0.3s ease, opacity 0.3s ease;
}

/* When being hidden */
#top-bar:not(.hidden-empty-topbar):empty,
.top-bar:not(.hidden-empty-topbar):empty {
    opacity: 0;
    height: 0;
}

/* Common empty states to hide */
#top-bar:has(> *:empty:only-child),
.top-bar:has(> *:empty:only-child) {
    display: none !important;
}

/* Hide if only contains whitespace */
#top-bar:not(:has(*)),
.top-bar:not(:has(*)) {
    display: none !important;
}

/* Responsive hiding for different devices */
@media (max-width: 480px) {
    /* Extra small devices */
    #top-bar:not(:has(.login)):not(:has(.register)),
    .top-bar:not(:has(.login)):not(:has(.register)) {
        display: none !important;
    }
}

@media (min-width: 481px) and (max-width: 768px) {
    /* Small devices */
    #top-bar:not(:has(.account)),
    .top-bar:not(:has(.account)) {
        display: none !important;
    }
}

@media (min-width: 769px) and (max-width: 1024px) {
    /* Tablets */
    #top-bar:empty,
    .top-bar:empty {
        display: none !important;
    }
}

/* Prevent layout shift */
#top-bar:not(.hidden-empty-topbar) {
    min-height: 0;
}

/* Override theme styles that might force display */
.site-header:has(+ #top-bar.hidden-empty-topbar),
.site-header:has(+ .top-bar.hidden-empty-topbar) {
    margin-top: 0 !important;
    padding-top: 0 !important;
}

/**
 * Hide/Remove NASA Breadcrumb Elements
 * Targets: Static Blocks breadcrumb in admin/frontend
 */

(function() {
    'use strict';

    /**
     * Remove breadcrumb elements
     */
    function removeBreadcrumbs() {
        // Select all matching breadcrumb elements
        var breadcrumbs = document.querySelectorAll('span.nasa-flex.jc');

        breadcrumbs.forEach(function(breadcrumb) {
            // Check if it contains the specific text pattern
            var text = breadcrumb.textContent || breadcrumb.innerText;

            if (text.includes('Dashboard') && text.includes('Static Blocks')) {
                // Remove the entire element from DOM
                breadcrumb.remove();

                // Also check if parent is empty and remove it
                var parent = breadcrumb.parentElement;
                if (parent && parent.children.length === 0) {
                    parent.remove();
                }
            }
        });

        // Alternative method for browsers without :has() support
        try {
            // Try using :has() selector
            var specificBreadcrumbs = document.querySelectorAll('span.nasa-flex.jc:has(i.pe-7s-news-paper)');
            specificBreadcrumbs.forEach(function(el) {
                el.remove();
            });
        } catch (e) {
            // Fallback for browsers without :has() support
            var allNasaFlex = document.querySelectorAll('span.nasa-flex.jc');
            allNasaFlex.forEach(function(span) {
                // Check if contains the newspaper icon
                if (span.querySelector('i.pe-7s-news-paper') || 
                    span.querySelector('i.pe7-icon.pe-7s-news-paper')) {
                    span.remove();
                }
            });
        }
    }

    /**
     * Observer for dynamic content
     */
    function setupObserver() {
        // Create observer to watch for dynamically added elements
        var observer = new MutationObserver(function(mutations) {
            mutations.forEach(function(mutation) {
                if (mutation.addedNodes.length) {
                    removeBreadcrumbs();
                }
            });
        });

        // Start observing
        observer.observe(document.body, {
            childList: true,
            subtree: true
        });
    }

    /**
     * Initialize on various load events
     */
    function init() {
        // Remove on initial load
        removeBreadcrumbs();

        // Setup observer for dynamic content
        setupObserver();

        // Also run after a short delay to catch late-loading elements
        setTimeout(removeBreadcrumbs, 500);
        setTimeout(removeBreadcrumbs, 1000);
    }

    // Run when DOM is ready
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', init);
    } else {
        init();
    }

    // Also run on window load
    window.addEventListener('load', function() {
        removeBreadcrumbs();
    });

})();

/**
 * Hide Empty Top Bar
 * Checks if #top-bar contains login/register content
 * If not, hides the entire top bar across all devices
 */

(function() {
    'use strict';

    /**
     * Check if element contains login/register content
     */
    function hasLoginRegisterContent(element) {
        if (!element) return false;

        var text = element.textContent || element.innerText || '';
        text = text.toLowerCase();

        // Check for login/register keywords
        var keywords = [
            'login', 'log in', 'signin', 'sign in',
            'register', 'signup', 'sign up', 'create account',
            'my account', 'account', 'logout', 'log out',
            'đăng nhập', 'đăng ký', 'tài khoản' // Vietnamese
        ];

        // Check text content
        for (var i = 0; i < keywords.length; i++) {
            if (text.includes(keywords[i])) {
                return true;
            }
        }

        // Check for login/register links
        var links = element.querySelectorAll('a');
        for (var j = 0; j < links.length; j++) {
            var href = links[j].href || '';
            var linkText = links[j].textContent || links[j].innerText || '';

            // Check href
            if (href.includes('login') || href.includes('register') || 
                href.includes('account') || href.includes('signin') ||
                href.includes('wp-login')) {
                return true;
            }

            // Check link text
            for (var k = 0; k < keywords.length; k++) {
                if (linkText.toLowerCase().includes(keywords[k])) {
                    return true;
                }
            }
        }

        // Check for login forms
        if (element.querySelector('form[name*="login"], form[id*="login"], form.login-form')) {
            return true;
        }

        // Check for specific login/register classes
        var loginClasses = [
            '.login', '.register', '.account', '.signin',
            '.nasa-login', '.topbar-account', '.account-element'
        ];

        for (var l = 0; l < loginClasses.length; l++) {
            if (element.querySelector(loginClasses[l])) {
                return true;
            }
        }

        return false;
    }

    /**
     * Process top bar visibility
     */
    function processTopBar() {
        var topBar = document.getElementById('top-bar');
        if (!topBar) {
            topBar = document.querySelector('.top-bar');
        }

        if (topBar) {
            // Check if has login/register content
            if (!hasLoginRegisterContent(topBar)) {
                // Hide the top bar
                topBar.style.display = 'none';
                topBar.style.visibility = 'hidden';
                topBar.style.height = '0';
                topBar.style.overflow = 'hidden';
                topBar.setAttribute('aria-hidden', 'true');

                // Add class for CSS targeting
                topBar.classList.add('hidden-empty-topbar');

                // Adjust body padding if needed
                var body = document.body;
                var computedStyle = window.getComputedStyle(body);
                var currentPaddingTop = parseInt(computedStyle.paddingTop) || 0;

                // If body has padding-top that matches topbar height, remove it
                if (currentPaddingTop > 0 && currentPaddingTop <= 50) {
                    body.style.paddingTop = '0';
                }

                // Also check for margin-top on common wrapper elements
                var wrappers = ['.wrapper', '#wrapper', '.site-wrapper', 'header'];
                wrappers.forEach(function(selector) {
                    var element = document.querySelector(selector);
                    if (element) {
                        var style = window.getComputedStyle(element);
                        var marginTop = parseInt(style.marginTop) || 0;
                        if (marginTop > 0 && marginTop <= 50) {
                            element.style.marginTop = '0';
                        }
                    }
                });

            } else {
            }
        }
    }

    /**
     * Initialize on various events
     */
    function init() {
        // Process immediately
        processTopBar();

        // Process after delay for dynamic content
        setTimeout(processTopBar, 500);
        setTimeout(processTopBar, 1000);

        // Watch for changes
        var observer = new MutationObserver(function(mutations) {
            var shouldRecheck = false;

            mutations.forEach(function(mutation) {
                if (mutation.type === 'childList' && mutation.addedNodes.length > 0) {
                    // Check if top bar was added or modified
                    mutation.addedNodes.forEach(function(node) {
                        if (node.nodeType === 1) { // Element node
                            if (node.id === 'top-bar' || node.classList && node.classList.contains('top-bar')) {
                                shouldRecheck = true;
                            }
                        }
                    });
                }
            });

            if (shouldRecheck) {
                processTopBar();
            }
        });

        // Start observing
        observer.observe(document.body, {
            childList: true,
            subtree: true
        });
    }

    // Initialize when DOM is ready
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', init);
    } else {
        init();
    }

    // Also run on window load
    window.addEventListener('load', processTopBar);

    // Re-check on resize (responsive changes)
    var resizeTimeout;
    window.addEventListener('resize', function() {
        clearTimeout(resizeTimeout);
        resizeTimeout = setTimeout(processTopBar, 250);
    });

})();

