.nasa-tip-content {
  position: absolute;
  top: -10px;
  left: 50%;
  visibility: hidden;
  opacity: 0;
  z-index: 9999;
  width: auto;
  height: auto;
  background: #333;
  border-color: #333;
  color: #fff;
  white-space: nowrap;
  text-transform: none;
  font-size: 12px;
  font-weight: normal;
  line-height: 1.4;
  padding: 5px 8px;
  -webkit-box-shadow: none;
  -moz-box-shadow: none;
  box-shadow: none;
  -webkit-border-radius: 2px;
  -moz-border-radius: 2px;
  border-radius: 2px;
  -webkit-transform: translate(-50%, -100%);
  -moz-transform: translate(-50%, -100%);
  -o-transform: translate(-50%, -100%);
  -ms-transform: translate(-50%, -100%);
  transform: translate(-50%, -100%);
}
.nasa-tip-content:after {
  top: 95%;
  left: 50%;
  content: " ";
  height: 0;
  width: 0;
  position: absolute;
  pointer-events: none;
  border: solid transparent;
  border-color: transparent;
  border-top-color: inherit;
  border-width: 6px;
  margin-left: -6px;
}

